#include <datamunge/optim/augmented_lagrangian.hpp>
#include <cmath>
#include <stdexcept>
namespace datamunge::optim { AugmentedLagrangian::AugmentedLagrangian(AugmentedLagrangianOptions o):options_(o){} double AugmentedLagrangian::optimize(EqualityConstrainedFunction& f,std::vector<double>& x)const{if(options_.step_size<=0||options_.initial_penalty<=0)throw std::invalid_argument("AugmentedLagrangian: positive step_size and penalty required");auto c=f.constraints(x);std::vector<double> lambda(c.size());double rho=options_.initial_penalty;for(std::size_t outer=0;outer<options_.max_outer_iterations;++outer){for(std::size_t inner=0;inner<options_.inner_iterations;++inner){auto g=f.gradient(x);c=f.constraints(x);auto j=f.constraint_jacobian(x);for(std::size_t k=0;k<c.size();++k)for(std::size_t p=0;p<x.size();++p)g[p]+=(lambda[k]+rho*c[k])*j[k][p];double n=0;for(double q:g)n+=q*q;double scale=std::min(1.0,1.0/(options_.step_size*std::sqrt(n)+1e-12));for(std::size_t p=0;p<x.size();++p)x[p]-=scale*options_.step_size*g[p];}c=f.constraints(x);double n=0;for(std::size_t k=0;k<c.size();++k){lambda[k]+=rho*c[k];n+=c[k]*c[k];}if(std::sqrt(n)<=options_.tolerance)break;rho*=2;}return f.evaluate(x);}}
